//! Disposable benchmark of Execution's existing reference visitor operation.
#[path = "../tests/support/oop.rs"] mod oop;
use birnam_abi::size;
use birnam_artifact_codec::portable_program::{encode,NodeSpec,ProgramSpec,StatementSpec};
unsafe extern "C" {fn clock_gettime_nsec_np(clock:u32)->u64;}
fn main(){
 let h=oop::bootstrap();let q=h.scope();let gc=h.named(b"GC").unwrap();let execution=h.named(b"Execution").unwrap();
 let module=h.load_native(&q,&std::env::current_dir().unwrap().join(".cargo-target/reference-fallback-20261029/provider.dylib"),&[h.named(b"nil").unwrap()]).unwrap();
 let key=|n:&[u8]|q.keep(h.intern(n).unwrap()).unwrap();let declared=|n:&[u8]|q.call(module,b"methodAt:",&[key(n)]).unwrap();
 let state=q.call(h.id.root,b"sequence",&[declared(b"entry"),std::ptr::null_mut()]).unwrap();
 let factory=q.call(declared(b"factory"),b"withContext:",&[state]).unwrap();
 let encoded=encode(ProgramSpec{parameters:&[],captures:&[],lets:&[],statements:&[StatementSpec::Expression{root_node:0}],nodes:&[NodeSpec::Nil]}).unwrap();
 let bytes=q.call(h.named(b"Bytes").unwrap(),b"fromBytes:",&[q.byte_values(&encoded).unwrap()]).unwrap();
 let code=q.call(h.named(b"CodeObject").unwrap(),b"fromCanonicalBytes:",&[bytes]).unwrap();
 let method=q.call(execution,b"fromNativeCodeFactory:codeObject:",&[factory,code]).unwrap();
 let context=q.call(state,b"at:",&[size(1).unwrap()]).unwrap();
 let block=q.call(h.named(b"Block").unwrap(),b"fromMethod:captureOperands:",&[method]).unwrap();
 let behavior=q.call(h.named(b"ObjectVt").unwrap(),b"delegated",&[]).unwrap();
 q.call(behavior,b"addMethod",&[key(b"visit:"),declared(b"visit:")]).unwrap();
 let visitor=q.call(behavior,b"allocate",&[size(0).unwrap()]).unwrap();let selector=key(b"referencesOf:do:");
 for (name,object,edges) in [("native",context,vec![factory,code,method]),("block",block,vec![method])] {
  let arguments=q.call(h.id.root,b"sequence",&edges).unwrap();
  q.call(declared(b"configure"),b"invokeOn:arguments:",&[module,arguments]).unwrap();
  for sample in 0..7 {
   q.call(gc,b"collectPrecisely",&[]).unwrap();let calls=50000;let start=unsafe{clock_gettime_nsec_np(16)};
   for _ in 0..calls {assert!(unsafe{h.id.send(execution,selector,&[object,visitor]).unwrap()}.is_null());}
   println!("{name} {sample} {calls} {}",unsafe{clock_gettime_nsec_np(16)}-start);
  }
 }
 assert_eq!(q.call(block,b"value",&[]).unwrap(),h.named(b"nil").unwrap());
}

