/* Test provider: records the context supplied to its own code factory. */
#include "../../tests/fixtures/oop-id-v2/id.h"
static IdProtocol id; static Oop names[7], expected[4], answer; static size_t count, visits;
enum { AT, PUT, WITH, FACTORY, ENTRY, VISIT, CONFIGURE };
#define CHECK(v) do { Oop checked=(v); if(id_fault(checked)) return checked; } while(0)
static Oop factory(Oop root,Oop c,Oop r,const Oop*a,size_t n){
 (void)root;(void)r;if(n!=2)return id.invalid;
 Oop zero=id_size(0),entry=id.message(id.root,c,names[AT],&zero,1);CHECK(entry);
 Oop saved[]={id_size(1),a[0]};CHECK(id.message(id.root,c,names[PUT],saved,2));
 return id.message(id.root,entry,names[WITH],a,1);
}
static Oop entry(Oop root,Oop c,Oop r,const Oop*a,size_t n){(void)root;(void)c;(void)r;(void)a;(void)n;return answer;}
static Oop visit(Oop root,Oop c,Oop r,const Oop*a,size_t n){
 (void)root;(void)c;(void)r;if(n!=1||!count||a[0]!=expected[visits%count])return id.invalid;visits++;return 0;
}
static Oop configure(Oop root,Oop c,Oop r,const Oop*a,size_t n){
 (void)root;(void)c;(void)r;if(!n||n>4)return id.invalid;count=n;visits=0;for(size_t i=0;i<n;i++)expected[i]=a[i];return 0;
}
static Oop initialize(const IdProtocol*p,Oop image,const Oop*s,size_t n,const Oop*a,size_t argc){
 if(n!=7||argc!=1)return p->invalid;answer=a[0];id=*p;for(size_t i=0;i<n;i++)names[i]=s[i];return image;
}
static const IdLiteral literals[]={LIT("at:"),LIT("at:put:"),LIT("withContext:"),LIT("factory"),LIT("entry"),LIT("visit:"),LIT("configure")};
static const IdMethodSpec methods[]={{FACTORY,factory},{ENTRY,entry},{VISIT,visit},{CONFIGURE,configure}};
const IdModule birnam_native_module_v2={2,sizeof(IdModule),literals,7,methods,4,initialize};

